import { useEffect, useState } from "react";
import {
  Bot,
  ChevronLeft,
  ChevronRight,
  Clock,
  Download,
  FolderGit2,
  LayoutDashboard,
  Rocket,
  Settings as SettingsIcon,
  SquareTerminal,
  KeyRound,
} from "lucide-react";
import clsx from "clsx";
import { useT } from "../lib/i18n";
// @ts-ignore wailsjs bindings are generated by wails build
import { AppVersion } from "../../wailsjs/go/controllers/System";

export type Page =
  | "dashboard"
  | "projects"
  | "terminal"
  | "ssh"
  | "cron"
  | "deployments"
  | "downloads"
  | "agents"
  | "settings";

const NAV: { id: Page; key: string; icon: typeof LayoutDashboard }[] = [
  { id: "dashboard", key: "nav.dashboard", icon: LayoutDashboard },
  { id: "projects", key: "nav.projects", icon: FolderGit2 },
  { id: "terminal", key: "nav.terminal", icon: SquareTerminal },
  { id: "ssh", key: "nav.ssh", icon: KeyRound },
  { id: "cron", key: "nav.cron", icon: Clock },
  { id: "deployments", key: "nav.deployments", icon: Rocket },
  { id: "downloads", key: "nav.downloads", icon: Download },
  { id: "agents", key: "nav.agents", icon: Bot },
  { id: "settings", key: "nav.settings", icon: SettingsIcon },
];

const STORAGE_KEY = "kd:sidebar-collapsed";

export default function Sidebar({ page, onNavigate }: { page: Page; onNavigate: (page: Page) => void }) {
  const t = useT();
  const [collapsed, setCollapsed] = useState(() => localStorage.getItem(STORAGE_KEY) === "1");
  const [version, setVersion] = useState("");

  useEffect(() => {
    AppVersion()
      .then((v: string) => setVersion(v))
      .catch(() => { /* pre-startup or a test: leave blank */ });
  }, []);

  const toggle = () => {
    setCollapsed((current) => {
      localStorage.setItem(STORAGE_KEY, current ? "0" : "1");
      return !current;
    });
  };

  return (
    <aside
      className={clsx(
        "flex h-full flex-col border-r border-white/10 bg-black/20 backdrop-blur-md transition-all duration-200",
        collapsed ? "w-[56px]" : "w-[200px]",
      )}
    >
      <div className="flex items-center gap-2 px-3 pt-3 pb-2">
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-accent/20 text-sm font-bold text-accent2">
          K
        </div>
        {!collapsed && (
          <span className="truncate text-sm font-semibold tracking-wide text-white/90">
            Kito<span className="brand-dock">dock</span>
          </span>
        )}
      </div>

      <nav className="mt-1 flex flex-1 flex-col gap-0.5 px-2" aria-label={t("nav.dashboard")}>
        {NAV.map(({ id, key, icon: Icon }) => (
          <button
            key={id}
            type="button"
            onClick={() => onNavigate(id)}
            title={collapsed ? t(key) : undefined}
            aria-current={page === id ? "page" : undefined}
            className={clsx(
              "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-left text-[13px] transition-colors",
              page === id
                ? "bg-accent/20 text-white"
                : "text-white/60 hover:bg-white/5 hover:text-white/90",
            )}
          >
            <Icon className="h-4 w-4 shrink-0" />
            {!collapsed && <span className="truncate">{t(key)}</span>}
          </button>
        ))}
      </nav>

      <div className="flex items-center justify-between border-t border-white/10 px-2 py-2">
        {!collapsed && version && (
          <span className="truncate px-1 text-[10px] text-white/35">{t("sidebar.version", { version })}</span>
        )}
        <button
          type="button"
          onClick={toggle}
          aria-label={collapsed ? t("sidebar.expand") : t("sidebar.collapse")}
          title={collapsed ? t("sidebar.expand") : t("sidebar.collapse")}
          className="flex h-7 w-7 items-center justify-center rounded text-white/50 hover:bg-white/10 hover:text-white"
        >
          {collapsed ? <ChevronRight className="h-3.5 w-3.5" /> : <ChevronLeft className="h-3.5 w-3.5" />}
        </button>
      </div>
    </aside>
  );
}
